Here's the step-by-step approach:

1. **Generate all possible degree sequences**: We need to generate all possible degree sequences \( d_1, d_2, \ldots, d_{10} \) such that:
   - \( d_i \geq d_{i+1} \)
   - Each degree \( d_i > 0 \) and \( d_i \equiv 0 \pmod{3} \)
   - The sum of the degrees is \( \equiv 0 \pmod{12} \)

2. **Check for diamond-free graph**: For each valid degree sequence, we need to check if there exists a simple diamond-free graph with that degree sequence. This can be done using the Havel-Hakimi algorithm to construct a graph and then checking for the diamond-free property.

3. **Print the adjacency matrix**: If a valid diamond-free graph is found, print its adjacency matrix.

Let's implement this in Python using OR-Tools for constraint satisfaction and additional logic to check for the diamond-free property.

```python
import itertools
import json
from ortools.sat.python import cp_model

def is_diamond_free(graph):
    n = len(graph)
    for nodes in itertools.combinations(range(n), 4):
        subgraph = [graph[i][j] for i in nodes for j in nodes if i < j]
        if sum(subgraph) > 4:
            return False
    return True

def generate_degree_sequences(n):
    degree_sequences = []
    for d1 in range(3, n*3 + 1, 3):
        for d2 in range(0, d1 + 1, 3):
            for d3 in range(0, d2 + 1, 3):
                for d4 in range(0, d3 + 1, 3):
                    for d5 in range(0, d4 + 1, 3):
                        for d6 in range(0, d5 + 1, 3):
                            for d7 in range(0, d6 + 1, 3):
                                for d8 in range(0, d7 + 1, 3):
                                    for d9 in range(0, d8 + 1, 3):
                                        for d10 in range(0, d9 + 1, 3):
                                            degree_sequence = [d1, d2, d3, d4, d5, d6, d7, d8, d9, d10]
                                            if sum(degree_sequence) % 12 == 0:
                                                degree_sequences.append(degree_sequence)
    return degree_sequences

def havel_hakimi(degree_sequence):
    degree_sequence = sorted(degree_sequence, reverse=True)
    while degree_sequence:
        d = degree_sequence.pop(0)
        if d > len(degree_sequence):
            return False
        for i in range(d):
            degree_sequence[i] -= 1
            if degree_sequence[i] < 0:
                return False
        degree_sequence = sorted(degree_sequence, reverse=True)
    return True

def construct_graph(degree_sequence):
    n = len(degree_sequence)
    graph = [[0] * n for _ in range(n)]
    degree_sequence = sorted(degree_sequence, reverse=True)
    nodes = list(range(n))
    while degree_sequence:
        d = degree_sequence.pop(0)
        node = nodes.pop(0)
        for _ in range(d):
            neighbor = nodes.pop(0)
            graph[node][neighbor] = 1
            graph[neighbor][node] = 1
            degree_sequence[degree_sequence.index(degree_sequence[0] - 1)] -= 1
            degree_sequence = sorted(degree_sequence, reverse=True)
    return graph

def main():
    n = 10
    degree_sequences = generate_degree_sequences(n)
    for degree_sequence in degree_sequences:
        if havel_hakimi(degree_sequence):
            graph = construct_graph(degree_sequence)
            if is_diamond_free(graph):
                solution = {
                    'matrix': graph
                }
                print(json.dumps(solution, indent=4))
                return
    print("No solution found.")

if __name__ == "__main__":
    main()
```

